/// Returns `(path relative to the repository root, file content)` for every generated file.
pub fn render(tables: &Tables, commit: &str) -> Vec<(String, String)> {
    vec![
        (
            format!("{OUTPUT_DIR}/functions.rs"),
            functions(tables, commit),
        ),
        (
            format!("{OUTPUT_DIR}/key_bindings.rs"),
            key_bindings(tables, commit),
        ),
        (
            format!("{OUTPUT_DIR}/main_menu.rs"),
            main_menu(tables, commit),
        ),
    ]
}

/// A label as UME Editor shows it: Sakura's product name in it (サクラエディタ, as in
/// 「サクラエディタの全終了」) becomes ours (ウメエディタ).
fn ume_label(label: &str) -> String {
    label.replace("サクラエディタ", "ウメエディタ")
}

fn header(commit: &str, sources: &[&str]) -> String {
    let mut out = String::new();
    out.push_str(
        "// @generated by `cargo xtask sakura-tables --sakura <path to a Sakura clone>`.\n",
    );
    out.push_str(
        "// Do not edit by hand; change the generator (xtask/src) and run it again.\n//\n",
    );
    let _ = writeln!(out, "// Source: Sakura Editor, commit {commit}");
    out.push_str("//   https://github.com/sakura-editor/sakura\n");
    for source in sources {
        let _ = writeln!(out, "//   {source}");
    }
    out.push_str("//\n// This file is derived from the files above and was modified: the data was converted\n");
    out.push_str(
        "// to Rust tables, names were converted to command IDs, and labels were resolved (the\n\
         // product name サクラエディタ in a label became ウメエディタ). UME Editor's own functions\n\
         // (xtask/src/ume_extras.rs) were added.\n//\n",
    );
    for line in NOTICE.lines() {
        if line.is_empty() {
            out.push_str("//\n");
        } else {
            let _ = writeln!(out, "// {line}");
        }
    }
    out.push('\n');
    out
}

fn functions(tables: &Tables, commit: &str) -> String {
    let mut out = header(
        commit,
        &[parse::HSRC, parse::RC_H, parse::RC, parse::FUNCCODE_CPP],
    );
    out.push_str("use super::{Function, FunctionKind::*};\n\n");
    out.push_str("/// Names of the function groups of the customize dialogs, in Sakura's order.\n");
    out.push_str("/// `Function::groups` holds indexes into this list.\n");
    out.push_str("pub static FUNCTION_GROUPS: &[&str] = &[\n");
    for group in &tables.groups {
        let _ = writeln!(out, "    {group:?},");
    }
    out.push_str("];\n\n");
    out.push_str("/// Every function code of `Funccode_x.hsrc` and the menu label IDs of `sakura_rc.h`, in file\n");
    out.push_str("/// order. Range markers such as `F_MENU_FIRST` are left out.\n");
    out.push_str("#[rustfmt::skip]\n");
    out.push_str("pub static FUNCTIONS: &[Function] = &[\n");
    for f in &tables.functions {
        let groups: Vec<String> = f.groups.iter().map(usize::to_string).collect();
        let groups = groups.join(", ");
        let label = f
            .label
            .as_ref()
            .map_or("None".to_string(), |l| format!("Some({:?})", ume_label(l)));
        let _ = writeln!(
            out,
            "    Function {{ code: {}, name: {:?}, id: {:?}, kind: {}, groups: &[{groups}], label: {label} }},",
            f.code,
            f.name,
            f.id,
            f.kind.rust_name(),
        );
    }
    out.push_str("];\n");
    out
}

fn key_bindings(tables: &Tables, commit: &str) -> String {
    let mut out = header(commit, &[parse::KEYBIND_CPP, parse::KEYBIND_H, parse::RC]);
    out.push_str("use super::KeyBinding;\n\n");
    out.push_str(
        "/// Sakura's default key bindings (`KeyDataInit` in `CKeyBind.cpp`), in table order.\n",
    );
    out.push_str("/// `functions` holds function codes (0 = none) for: none, Shift, Ctrl, Shift+Ctrl, Alt,\n");
    out.push_str(
        "/// Shift+Alt, Ctrl+Alt, Shift+Ctrl+Alt. The comment of a row names the codes.\n",
    );
    out.push_str("#[rustfmt::skip]\n");
    out.push_str("pub static KEY_BINDINGS: &[KeyBinding] = &[\n");
    for key in &tables.keys {
        let codes: Vec<String> = key.functions.iter().map(u16::to_string).collect();
        let _ = write!(
            out,
            "    KeyBinding {{ key_code: {:#06x}, key_name: {:?}, functions: [{}] }},",
            key.key_code,
            key.key_name,
            codes.join(", "),
        );
        let names: Vec<String> = key
            .functions
            .iter()
            .enumerate()
            .filter(|&(_, &code)| code != 0)
            .map(|(slot, &code)| format!("{}={}", modifiers(slot), function_name(tables, code)))
            .collect();
        if !names.is_empty() {
            let _ = write!(out, " // {}", names.join(", "));
        }
        out.push('\n');
    }
    out.push_str("];\n");
    out
}

fn modifiers(slot: usize) -> String {
    let mut parts = Vec::new();
    if slot & 2 != 0 {
        parts.push("Ctrl");
    }
    if slot & 4 != 0 {
        parts.push("Alt");
    }
    if slot & 1 != 0 {
        parts.push("Shift");
    }
    if parts.is_empty() {
        "-".to_string()
    } else {
        parts.join("+")
    }
}

/// The Sakura name of the first function that has this code.
fn function_name(tables: &Tables, code: u16) -> &str {
    tables
        .functions
        .iter()
        .find(|f| f.code == code)
        .map_or("?", |f| f.name.as_str())
}

fn main_menu(tables: &Tables, commit: &str) -> String {
    let mut out = header(commit, &[parse::MAIN_MENU_INI, parse::RC, parse::HSRC]);
    out.push_str("use super::{MenuItem, MenuKind::*};\n\n");
    out.push_str("/// Whether the access keys are shown in parentheses, as in `File(F)`\n");
    out.push_str("/// (the first line of `MainMenu.ini`).\n");
    let _ = writeln!(
        out,
        "pub const KEY_PARENTHESES: bool = {};\n",
        tables.key_parentheses
    );
    out.push_str("/// Sakura's default main menu: a tree in depth-first order. `level` 0 items are the menu\n");
    out.push_str("/// bar; an item belongs to the closest earlier item with a smaller level. Labels are the\n");
    out.push_str("/// raw string-table text (`&&` is a literal `&`).\n");
    out.push_str("#[rustfmt::skip]\n");
    out.push_str("pub static MAIN_MENU: &[MenuItem] = &[\n");
    for item in &tables.menu {
        let key = item
            .access_key
            .map_or("None".to_string(), |c| format!("Some({c:?})"));
        let label = item
            .label
            .as_ref()
            .map_or("None".to_string(), |l| format!("Some({:?})", ume_label(l)));
        let _ = writeln!(
            out,
            "    MenuItem {{ level: {}, kind: {}, code: {}, access_key: {key}, label: {label} }},",
            item.level,
            item.kind.rust_name(),
            item.code,
        );
    }
    out.push_str("];\n");
    out
}
